<?php
namespace Modules\Ran\Reports;
class InventoryValuationReport extends AbstractRanReport{public function title():string{return 'Inventory Valuation';}public function headings():array{return ['SKU','Item','Location','Store','Quantity','Net Weight','Value'];}public function rows(array $f):array{$q=\DB::table('ran_stock_lots as l')->join('ran_items as i','i.id','=','l.item_id')->whereNull('l.deleted_at')->whereNull('i.deleted_at')->where('l.business_id',\Modules\Ran\Support\RanContext::businessId());if(!empty($f['location_id']))$q->where('l.location_id',$f['location_id']);if(!empty($f['store_id']))$q->where('l.store_id',$f['store_id']);return $q->groupBy('i.sku','i.name','l.location_id','l.store_id')->orderBy('i.name')->get([ 'i.sku','i.name','l.location_id','l.store_id',\DB::raw('SUM(l.quantity) quantity'),\DB::raw('SUM(l.net_weight) net_weight'),\DB::raw('SUM(l.total_cost) value')])->map(fn($r)=>(array)$r)->all();}public function totals(array $rows):array{return ['Quantity'=>array_sum(array_column($rows,'quantity')),'Net Weight'=>array_sum(array_column($rows,'net_weight')),'Value'=>array_sum(array_column($rows,'value'))];}}
